// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ClearCart Empty the cart
	// (DELETE /cart)
	ClearCart(ctx context.Context, request ClearCartRequestObject) (ClearCartResponseObject, error)
	// GetCart Get the current client's cart
	// (GET /cart)
	GetCart(ctx context.Context, request GetCartRequestObject) (GetCartResponseObject, error)
	// AddCartItem Add a menu item to the cart
	// (POST /cart/items)
	AddCartItem(ctx context.Context, request AddCartItemRequestObject) (AddCartItemResponseObject, error)
	// RemoveCartItem Remove a line from the cart
	// (DELETE /cart/items/{itemId})
	RemoveCartItem(ctx context.Context, request RemoveCartItemRequestObject) (RemoveCartItemResponseObject, error)
	// UpdateCartItem Change the quantity of a cart line
	// (PATCH /cart/items/{itemId})
	UpdateCartItem(ctx context.Context, request UpdateCartItemRequestObject) (UpdateCartItemResponseObject, error)
	// CreateOrder Place an order from the current cart
	// (POST /orders)
	CreateOrder(ctx context.Context, request CreateOrderRequestObject) (CreateOrderResponseObject, error)
	// GetOrder Order status and its full transition history
	// (GET /orders/{orderId})
	GetOrder(ctx context.Context, request GetOrderRequestObject) (GetOrderResponseObject, error)
	// CancelOrder Cancel an order before the venue starts cooking it
	// (POST /orders/{orderId}/cancel)
	CancelOrder(ctx context.Context, request CancelOrderRequestObject) (CancelOrderResponseObject, error)
	// ListRescueOffers Cross-venue "rescue" feed, soonest-closing offer first
	// (GET /rescue)
	ListRescueOffers(ctx context.Context, request ListRescueOffersRequestObject) (ListRescueOffersResponseObject, error)
	// ListVenues List venues with filters and cursor pagination
	// (GET /venues)
	ListVenues(ctx context.Context, request ListVenuesRequestObject) (ListVenuesResponseObject, error)
	// GetVenue Venue card — details and weekly schedule
	// (GET /venues/{venueId})
	GetVenue(ctx context.Context, request GetVenueRequestObject) (GetVenueResponseObject, error)
	// GetVenueMenu Venue menu with live availability and rescue prices
	// (GET /venues/{venueId}/menu)
	GetVenueMenu(ctx context.Context, request GetVenueMenuRequestObject) (GetVenueMenuResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

